// Stand-in for `virtual:pwa-register/react` during vitest runs. The real
// module is generated by vite-plugin-pwa at build time, so it doesn't
// resolve in the vitest pipeline. Vitest's vitest.config.ts aliases the
// virtual specifier to this file so component tests can `vi.mock` on top
// without hitting an "unresolved import" transform error.
export function useRegisterSW() {
  return {
    needRefresh: [false, () => {}] as [boolean, (v: boolean) => void],
    offlineReady: [false, () => {}] as [boolean, (v: boolean) => void],
    updateServiceWorker: async (_reload?: boolean) => undefined,
  };
}
